python3 -c "
import socket
import time

domain = 'example.com'

print(f'DNS Health Check for: {domain}')
print('=' * 50)

resolvers = {
    'System Default': None,
    'Google DNS': '8.8.8.8',
    'Cloudflare DNS': '1.1.1.1',
    'Quad9': '9.9.9.9'
}

results = {}

for name, resolver in resolvers.items():
    try:
        start = time.time()

        if resolver:
            import dns.resolver
            resolver_obj = dns.resolver.Resolver()
            resolver_obj.nameservers = [resolver]
            resolver_obj.timeout = 5
            resolver_obj.lifetime = 5
            answers = resolver_obj.resolve(domain, 'A')
            ip = str(answers[0])
        else:
            ip = socket.gethostbyname(domain)

        latency = (time.time() - start) * 1000
        results[name] = {'status': 'ok', 'ip': ip, 'latency_ms': round(latency, 2)}
        print(f'[{name}] Status: OK | IP: {ip} | Latency: {latency:.2f}ms')
    except Exception as e:
        results[name] = {'status': 'error', 'error': str(e)}
        print(f'[{name}] Status: ERROR | {e}')

print()
print('DNS Record Types:')
print('-' * 50)

try:
    import dns.resolver

    record_types = ['A', 'AAAA', 'CNAME', 'MX', 'TXT', 'NS', 'SOA']
    for rtype in record_types:
        try:
            answers = dns.resolver.resolve(domain, rtype)
            records = [str(r) for r in answers]
            if records:
                print(f'{rtype}: {records[0][:60]}')
            else:
                print(f'{rtype}: (no record)')
        except dns.resolver.NoAnswer:
            print(f'{rtype}: (no record)')
        except Exception as e:
            print(f'{rtype}: error - {e}')
except ImportError:
    print('dnspython not installed, using basic resolution only')

    record_types = ['A', 'AAAA']
    for rtype in record_types:
        try:
            if rtype == 'A':
                ip = socket.gethostbyname(domain)
                print(f'{rtype}: {ip}')
            elif rtype == 'AAAA':
                ip = socket.gethostbyname_ex(domain)[2]
                print(f'{rtype}: {ip}')
        except Exception as e:
            print(f'{rtype}: error - {e}')

print()
print('Summary:')
print('-' * 50)
ok_count = sum(1 for r in results.values() if r['status'] == 'ok')
avg_latency = sum(r['latency_ms'] for r in results.values() if r['status'] == 'ok') / max(ok_count, 1)
print(f'Resolvers responding: {ok_count}/{len(resolvers)}')
print(f'Average latency: {avg_latency:.2f}ms')
print(f'Overall Health: {'✅ good' if ok_count >= 2 else '⚠️ degraded' if ok_count >= 1 else '❌ bad'}')
"

